#include <algorithm>
#include <iostream>
#include <numeric>
#include <tuple>
#include <vector>
using namespace std;

static vector<int> parent_;
int find_root(int x) {
    while (parent_[x] != x) {
        parent_[x] = parent_[parent_[x]];
        x = parent_[x];
    }
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<tuple<long long, int, int>> edges(m);
    for (auto& [w, u, v] : edges) cin >> u >> v >> w;
    sort(edges.begin(), edges.end());
    parent_.resize(n);
    iota(parent_.begin(), parent_.end(), 0);
    long long total = 0;
    int taken = 0;
    for (const auto& [w, u, v] : edges) {
        int a = find_root(u), b = find_root(v);
        if (a != b) {
            parent_[a] = b;
            total += w;
            taken++;
        }
    }
    cout << (taken == n - 1 ? total : -1) << '\n';
    return 0;
}

